686	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
687	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
688	fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
689	    debug!("longs: name={}", p.get_name());
690	
691	    p.get_arguments()
692	        .filter_map(|a| {
693	            a.get_long_and_visible_aliases().map(|longs| {
694	                longs
695	                    .into_iter()
696	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
697	            })
698	        })
699	        .flatten()
700	        .collect()
701	}
