703	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
704	fn hidden_longs_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
705	    debug!("longs: name={}", p.get_name());
706	
707	    p.get_arguments()
708	        .filter_map(|a| {
709	            a.get_aliases().map(|longs| {
710	                longs.into_iter().map(|s| {
711	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
712	                })
713	            })
714	        })
715	        .flatten()
716	        .collect()
717	}
