719	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
720	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
721	fn shorts_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
