727	                shorts.into_iter().map(|s| {
728	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
729	                        a.get_help()
730	                            .cloned()
731	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
732	                    )
733	                })
734	            })
735	        })
