765	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
766	///
767	/// Subcommand `rustup toolchain install` would be converted to
768	/// `("install", "rustup toolchain install")`.
769	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
770	    debug!("subcommands: name={}", p.get_name());
771	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
772	    p.get_subcommands()
773	        .flat_map(|sc| {
774	            sc.get_name_and_visible_aliases()
775	                .into_iter()
776	                .map(|s| populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc))
777	                .chain(sc.get_aliases().map(|s| {
778	                    populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc)
779	                        .hide(true)
780	                }))
781	        })
782	        .collect()
783	}
