249	/// Quote `s` for embedding inside fish's `--arguments` value.
250	///
251	/// Fish parses `--arguments` twice: once when sourcing the registration (the
252	/// outer double-quoted string) and again when evaluating the embedded command
253	/// substitution at completion time. Each special character must therefore
254	/// survive two rounds of unescaping, which is what this helper does that
255	/// [`fish_quote`] does not.
256	fn fish_quote_for_eval(s: &str) -> std::borrow::Cow<'_, str> {
257	    if !fish_needs_quoting(s) {
258	        return std::borrow::Cow::Borrowed(s);
259	    }
260	    let mut out = String::with_capacity(s.len() + 2);
261	    out.push('\'');
262	    for c in s.chars() {
263	        match c {
264	            '\\' => out.push_str(r"\\\\"),
265	            '\'' => out.push_str(r"\\'"),
266	            '"' => out.push_str(r#"\""#),
267	            '$' => out.push_str(r"\$"),
268	            _ => out.push(c),
269	        }
270	    }
271	    out.push('\'');
272	    std::borrow::Cow::Owned(out)
273	}
