278	/// sourcing the registration and never re-evaluates it. Single-quoting plus
279	/// escaping `\` and `'` is sufficient.
280	fn fish_quote(s: &str) -> std::borrow::Cow<'_, str> {
281	    if !fish_needs_quoting(s) {
282	        return std::borrow::Cow::Borrowed(s);
283	    }
284	    let mut out = String::with_capacity(s.len() + 2);
285	    out.push('\'');
286	    for c in s.chars() {
287	        match c {
288	            '\\' => out.push_str(r"\\"),
289	            '\'' => out.push_str(r"\'"),
290	            _ => out.push(c),
291	        }
292	    }
293	    out.push('\'');
294	    std::borrow::Cow::Owned(out)
295	}
