1	//! [`COMPLETE=$SHELL <bin>`][CompleteEnv] completion integration
2	//!
3	//! See [`CompleteEnv`]:
4	//! ```rust
5	//! # use clap_complete::CompleteEnv;
6	//! fn cli() -> clap::Command {
7	//!     // ...
8	//! #   clap::Command::new("empty")
9	//! }
10	//!
11	//! CompleteEnv::with_factory(cli)
12	//!     .complete();
13	//!
14	//! // ... rest of application logic
15	//! ```
16	//!
17	//! To customize completions, see
18	//! - [`ValueHint`][crate::ValueHint]
19	//! - [`ValueEnum`][clap::ValueEnum]
20	//! - [`ArgValueCandidates`][crate::ArgValueCandidates]
21	//! - [`ArgValueCompleter`][crate::ArgValueCompleter]
22	//!
23	//! To source your completions:
24	//!
25	//! <div class="warning">
26	//!
27	//! **WARNING:** We recommend re-sourcing your completions on upgrade.
28	//! These completions work by generating shell code that calls into `your_program` while completing.
29	//! That interface is unstable and a mismatch between the shell code and `your_program` may result
30	//! in either invalid completions or no completions being generated.
31	//! For this reason, we recommend generating the shell code anew on shell startup so that it is
32	//! "self-correcting" on shell launch, rather than writing the generated completions to a file.
33	//!
34	//! </div>
35	//!
36	//! **Bash**
37	//! ```bash
38	//! echo "source <(COMPLETE=bash your_program)" >> ~/.bashrc
39	//! ```
40	//!
41	//! **Elvish**
42	//! ```elvish
43	//! echo "eval (E:COMPLETE=elvish your_program | slurp)" >> ~/.elvish/rc.elv
44	//! ```
45	//!
46	//! **Fish**
47	//! ```fish
48	//! echo "COMPLETE=fish your_program | source" >> ~/.config/fish/completions/your_program.fish
49	//! ```
50	//!
51	//! **Powershell**
52	//! ```powershell
53	//! echo '$env:COMPLETE = "powershell"; your_program | Out-String | Invoke-Expression; Remove-Item Env:\COMPLETE' >> $PROFILE
54	//! ```
55	//! Note that to execute scripts in PowerShell on Windows, including [`$PROFILE`][$Profile],
56	//! the [execution policy][ExecutionPolicies] needs to be set to `RemoteSigned` at minimum.
57	//!
58	//! [$Profile]: https://learn.microsoft.com/en-us/powershell/scripting/learn/shell/creating-profiles
59	//! [ExecutionPolicies]: https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_execution_policies
60	//!
61	//! **Zsh**
62	//! ```zsh
63	//! echo "source <(COMPLETE=zsh your_program)" >> ~/.zshrc
64	//! ```
65	//!
66	//! To disable completions, you can set `COMPLETE=` or `COMPLETE=0`
