        complete_argv(
            &mut parity_value_command(),
            &["tool", "--tag=red", "--tag="]
        ),
        tags
    );
    assert_eq!(
        complete_argv(
            &mut parity_value_command(),
            &["tool", "--tag", "red", "blue", "--tag", "bl"]
        ),
        vec!["blue"]
    );

    // Repeating a non-repeatable single-value option yields nothing.
    assert!(
        complete_argv(
            &mut parity_value_command(),
            &["tool", "--mode", "fast", "--mode", ""]
        )
        .is_empty()
    );
    assert!(
        complete_argv(
            &mut parity_value_command(),
            &["tool", "--mode=fast", "--mode=sa"]
        )
        .is_empty()
    );
    assert!(
        complete_argv(
            &mut parity_value_command(),
            &["tool", "--format", "json", "--format", ""]
        )
        .is_empty()
    );
    assert!(
        complete_argv(
            &mut parity_value_command(),
            &["tool", "--format=json", "--format=ya"]
        )
        .is_empty()
    );
}

