#![cfg(feature = "unstable-dynamic")]
use std::fs;
use clap::Command;
use clap_complete::engine::{ArgValueCandidates, CompletionCandidate};

fn run(cmd: &mut Command, argv: &[&str], dir: Option<&std::path::Path>) -> Vec<String> {
    let idx = argv.len() - 1;
    let args = argv.iter().map(std::ffi::OsString::from).collect();
    clap_complete::engine::complete(cmd, args, idx, dir).unwrap()
        .into_iter().map(|c| c.get_value().to_string_lossy().into_owned()).collect()
}

#[test]
fn attached_path_cwd_and_custom() {
    let testdir = snapbox::dir::DirRoot::mutable_temp().unwrap();
    let p = testdir.path().unwrap();
    fs::write(p.join("a_file"), "").unwrap();
    fs::create_dir_all(p.join("c_dir")).unwrap();

    let mut cmd = Command::new("tool")
        .arg(clap::Arg::new("input").long("input").value_hint(clap::ValueHint::FilePath))
        .arg(clap::Arg::new("tpl").long("tpl").add(ArgValueCandidates::new(|| {
            vec![CompletionCandidate::new("daily"), CompletionCandidate::new("weekly")]
        })));

    // Attached path completion honors current_dir and yields bare paths.
    let got = run(&mut cmd, &["tool", "--input="], Some(p));
    assert!(got.contains(&"a_file".to_owned()), "got={got:?}");
    assert!(got.contains(&"c_dir/".to_owned()), "got={got:?}");
    assert!(got.iter().all(|v| !v.starts_with("--input=")), "got={got:?}");

    // Attached custom candidates, partial prefix.
    let got = run(&mut cmd, &["tool", "--tpl=da"], None);
    assert_eq!(got, vec!["daily"]);
}
